import{_ as n,C as o,o as r,c as i,a3 as t,E as s}from"./chunks/framework.CZBGEXos.js";const w=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"en/getting-started.md","filePath":"en/getting-started.md"}'),l={name:"en/getting-started.md"};function d(h,e,c,p,u,g){const a=o("Screenshot");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Warden is a desktop crypto monitoring workspace for Windows. It reads publicly available market data from Bybit, Binance, Gate.io, OKX and Hyperliquid, and presents it through a set of purpose-built tools that each open in their own resizable window.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Download the installer with the <strong>Download</strong> button on <a href="https://cryptowarden.xyz/" target="_blank" rel="noreferrer">cryptowarden.xyz</a>.</li><li>Run the <code>.exe</code>.</li><li>Warden is Windows-only. There is no macOS or Linux build.</li></ol><h3 id="the-smartscreen-warning" tabindex="-1">The SmartScreen warning <a class="header-anchor" href="#the-smartscreen-warning" aria-label="Permalink to &quot;The SmartScreen warning&quot;">​</a></h3><p>On first download and run, <strong>Windows Defender SmartScreen may warn that the app is unrecognized</strong>. This is expected and is not a virus detection.</p><p>SmartScreen flags any new application that has not yet built up a reputation with Microsoft — it simply means not enough people have downloaded the file yet for it to be trusted automatically. Every new indie app goes through this, and the warning disappears on its own as the download count grows.</p><p>To get past it:</p><ol><li>Click <strong>More info</strong> on the SmartScreen popup.</li><li>Click <strong>Run anyway</strong>.</li><li>This only happens once — later launches won&#39;t show the warning.</li></ol><h2 id="first-run" tabindex="-1">First run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First run&quot;">​</a></h2><p>On launch Warden checks for updates before anything else, then asks you to sign in.</p><h3 id="account" tabindex="-1">Account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;Account&quot;">​</a></h3><p>Warden uses an email and password account. Signing up sends a 6-digit verification code to your email; enter it to confirm the address, then sign in. You&#39;ll also need to accept the Terms of Service during sign-up.</p><p>Access is currently free while Warden is in beta. Once signed in, the <strong>Home</strong> tab shows your subscription status as <code>Beta Test</code>, along with your email and the installed app version. Your email address is masked by default — click the eye icon next to it to reveal it.</p><div class="tip custom-block"><p class="custom-block-title">Warden never touches your exchange accounts</p><p>Every monitoring tool reads public market data only. Warden does not ask for exchange API keys, does not connect to your exchange account, and cannot place trades on any of the exchanges it monitors.</p><p>The one exception is the experimental <a href="/manual/en/tools/terminal.html">Terminal</a>, a separate opt-in tool that connects to Hyperliquid, Binance or Bybit with credentials you provide. It does nothing unless you deliberately set it up.</p></div><h2 id="the-workspace" tabindex="-1">The workspace <a class="header-anchor" href="#the-workspace" aria-label="Permalink to &quot;The workspace&quot;">​</a></h2>',16)),s(a,{src:"workspace",alt:"The full Warden workspace with several tool windows open",caption:"A Warden workspace — several tool windows arranged around the main window"}),e[1]||(e[1]=t('<p>Warden is built around one small <strong>main window</strong> plus one window per tool.</p><p>The main window&#39;s left edge is a vertical tab bar:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it holds</th></tr></thead><tbody><tr><td>Home</td><td>Account, language, accent color, chart and drawing settings</td></tr><tr><td>Knives</td><td><a href="/manual/en/tools/knives.html">Knives</a> settings + its <strong>Open Window</strong> button</td></tr><tr><td>Alerts</td><td><a href="/manual/en/tools/alerts.html">Alerts</a> settings + its <strong>Open Window</strong> button</td></tr><tr><td>Analyzer</td><td><a href="/manual/en/tools/analyzer.html">Analyzer</a> notices + its <strong>Open Window</strong> button</td></tr><tr><td>Monitor</td><td><a href="/manual/en/tools/monitor.html">Monitor</a> settings + its <strong>Open Window</strong> button</td></tr><tr><td>Terminal</td><td><a href="/manual/en/tools/terminal.html">Terminal</a> settings + its <strong>Open Window</strong> button</td></tr></tbody></table><p>Every tool works the same way: <strong>its settings live in the main window, and the tool itself opens as a separate window.</strong> Click <strong>Open Window</strong> in a tool&#39;s tab to launch it. While that window is open the button reads <strong>Already Open</strong> and is inert — each tool is limited to one window at a time.</p><p>Because each tool is an independent window, you can size and position them freely to build the layout you want, and leave the main window tucked away.</p><p>Changes to settings apply live — the open tool window picks them up without a restart. Settings are written to disk automatically as you change them.</p><h3 id="titlebar" tabindex="-1">Titlebar <a class="header-anchor" href="#titlebar" aria-label="Permalink to &quot;Titlebar&quot;">​</a></h3><p>Tool windows use Warden&#39;s own titlebar rather than the Windows one. It shows <code>WARDEN</code> and the active tool name on the left, and minimize / maximize / close on the right. Drag anywhere on the empty part of the bar to move the window.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>Warden&#39;s interface is available in English and Українська. Switch it in the <strong>Home</strong> tab, at the top right next to the WARDEN heading. This setting is independent of the language you&#39;re reading this manual in.</p><h2 id="accent-color" tabindex="-1">Accent color <a class="header-anchor" href="#accent-color" aria-label="Permalink to &quot;Accent color&quot;">​</a></h2><p>Also in the <strong>Home</strong> tab, the row of eight color swatches sets the app-wide accent color: Amber, Green, Blue, Purple, Red, Teal, Pink and White. It applies across every tool window.</p><p>This is separate from candle and metric colors — see <a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a> for those.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Warden updates itself. On every launch it checks for a new version before showing the sign-in screen; if one exists it downloads, installs and restarts automatically. You&#39;ll see <code>Checking for updates...</code> and then <code>Updating to v&lt;version&gt;...</code> on the loading screen while this happens.</p><p>There is nothing to do manually. The installed version is shown in the <strong>Home</strong> tab as <strong>App Version</strong>.</p><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><p>Bug reports and feature requests go to the <a href="https://t.me/+9d_deXPfxM81MGJi" target="_blank" rel="noreferrer">Telegram group</a> — it&#39;s the fastest way to get a direct response.</p>',18))])}const b=n(l,[["render",d]]);export{w as __pageData,b as default};
